changeSet.sql:
UPDATE bytedesk_kbase_service_settings
SET show_agent_avatar = b'1'
WHERE show_agent_avatar IS NULL OR show_agent_avatar = b'0';

UPDATE bytedesk_kbase_service_settings
SET show_agent_nickname = b'1'
WHERE show_agent_nickname IS NULL OR show_agent_nickname = b'0';

UPDATE bytedesk_kbase_service_settings
SET show_visitor_avatar = b'1'
WHERE show_visitor_avatar IS NULL OR show_visitor_avatar = b'0';

UPDATE bytedesk_kbase_service_settings
SET show_visitor_nickname = b'1'
WHERE show_visitor_nickname IS NULL OR show_visitor_nickname = b'0';

UPDATE bytedesk_kbase_service_settings
SET show_agent_avatar = TRUE
WHERE show_agent_avatar IS NULL OR show_agent_avatar = FALSE;

UPDATE bytedesk_kbase_service_settings
SET show_agent_nickname = TRUE
WHERE show_agent_nickname IS NULL OR show_agent_nickname = FALSE;

UPDATE bytedesk_kbase_service_settings
SET show_visitor_avatar = TRUE
WHERE show_visitor_avatar IS NULL OR show_visitor_avatar = FALSE;

UPDATE bytedesk_kbase_service_settings
SET show_visitor_nickname = TRUE
WHERE show_visitor_nickname IS NULL OR show_visitor_nickname = FALSE;
